INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C001', '自然呼吸観察', '["自然な呼吸の観察"]', 'practice', 'ヨガ呼吸の基礎', '実践', '呼吸に気づく', '["楽な姿勢で座り、背すじを軽く伸ばす。","肩、あご、お腹の力を抜く。","鼻から自然に吸い、鼻から自然に吐く。","呼吸を変えようとせず、流れを観察する。","目安は1〜3分です。"]', '["P13","P14","P23","P115"]', '["K011","K015","K016","K018","K013","K014","K017","K019","K036","K065"]', '["S001","S004"]', false, 'false', '[{"variant_id":"C001-V01","label":"第16章 呼吸観察から集中へ","source_passage_ids":["P115"],"steps_editorial":["楽に座り、自然な呼吸を感じる。","吸う息・吐く息に気づく。","呼吸が乱れたら責めずに戻る。"],"dose_source_text":"1〜3分","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false}]', '[{"issue_id":"I010","rule":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。"},{"issue_id":"I011","rule":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C002', 'ナディショーダナ簡易版', '["ナディショーダナ","ナディショーダナ／アヌローマ・ヴィローマ","アヌローマ・ヴィローマ","左右交互鼻呼吸"]', 'practice', 'ヨガ呼吸法', '実践', '左右の鼻を交互に使い、ゆっくり整える', '["楽な姿勢で座り、背すじと頭をまっすぐにする。","右手を鼻の前へ。親指で右鼻を軽く閉じ、左鼻から吸う。","薬指・小指で左鼻を軽く閉じ、同時に親指をゆるめ、右鼻から吐く。","そのまま右鼻から吸う。","親指で右鼻を軽く閉じ、同時に薬指・小指をゆるめ、左鼻から吐く。","ここまでを1往復とし、原稿では3〜5往復。息止めを入れない。"]', '["P16","P17","P23"]', '["K015","K016","K018","K013","K014","K017","K019"]', '["S001","S004"]', false, 'false', '[]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"},{"issue_id":"I010","rule":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。"},{"issue_id":"I011","rule":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C003', 'ブラーマリー簡易版', '["ブラーマリー","ハミング呼吸"]', 'practice', 'ヨガ呼吸法', '実践', '音と響きに注意を向ける', '["楽な姿勢で座り、目を閉じる。","鼻から静かに吸う。","吐くときに小さく「んー」と響かせる。","頭や顔に響く感覚を観察する。","原稿の目安は3〜5回。音を強く出さず、心地よい範囲で行う。"]', '["P20","P23"]', '["K015","K018","K013","K014","K017","K019"]', '["S001","S004"]', false, 'false', '[]', '[{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"},{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I010","rule":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。"},{"issue_id":"I011","rule":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C004', 'シータリー', '["シータリー呼吸"]', 'practice', 'ヨガ呼吸法', '紹介・体質配慮', '原稿では冷却・鎮静を目的として紹介', '["楽な姿勢で座る。","舌を筒状に丸め、その間からゆっくり吸う。","口を閉じ、鼻からゆっくり吐く。","原稿の目安は3〜5回。"]', '["P18","P19","P24"]', '["K015","K018","K019","K013","K014","K017"]', '["S001","S004"]', false, 'false', '[]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C005', 'カパラバティ', '["カパラーバーティ","Kapalabhati"]', 'practice', '浄化法・呼吸実践', '初心者は紹介のみ／経験者は指導者のもと', '特徴と安全管理を学ぶ', '[]', '["P21","P22","P23","P24"]', '["K016","K018","K013","K014","K015","K017","K019"]', '["S001","S004"]', false, 'false', '[]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I010","rule":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。"},{"issue_id":"I011","rule":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C006', 'ボックス呼吸', '["ボックス呼吸法","Box Breathing"]', 'practice', '現代呼吸法', '保息を含む概要・安全確認用', '集中・緊張調整として紹介', '["鼻から4秒吸う。","4秒息を止める。","4秒かけて吐く。","4秒息を止める。"]', '["P24","P25","P26","P082","P083","P084","P187","P188","P186","P205"]', '["K016","K017","K008","K013","K014","K015"]', '["S002","S004"]', false, 'false', '[{"variant_id":"C006-V01","label":"第6章の基本手順","source_passage_ids":["P082"],"steps_editorial":["鼻から4秒吸う。","4秒息を止める。","4秒かけて吐く。","4秒息を止める。"],"dose_source_text":"4〜5サイクル、約1〜2分","breath_hold":true,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C006-V02","label":"第7章のボックス呼吸","source_passage_ids":["P083","P187"],"steps_editorial":["吸う・止める・吐く・止めるを各4秒。"],"dose_source_text":"3〜5セット","breath_hold":true,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C006-V03","label":"原稿内のやさしいボックス（等間隔ではない）","source_passage_ids":["P084","P187"],"steps_editorial":["2秒吸う・1秒休む・3秒吐く・1秒休む。"],"dose_source_text":"3〜5セット（7-11の図で追加確認）","breath_hold":true,"route":null,"status":"overview_only","auto_selection_allowed":false},{"variant_id":"C006-V04","label":"7-12 本番3分前の例","source_passage_ids":["P188"],"steps_editorial":["吸う・止める・吐く・止めるを各4秒。"],"dose_source_text":"3〜4セット。本番3分前は開始する場面。","breath_hold":true,"route":null,"status":"overview_only","auto_selection_allowed":false},{"variant_id":"C006-V05","label":"導入図の名称未確定例","source_passage_ids":["P186"],"steps_editorial":["4秒吸う、4秒止める、6〜8秒吐く、4秒止めるという図示。"],"dose_source_text":"数分間という記載のみ。等時間の本文手順とは不一致。","breath_hold":true,"route":null,"status":"withheld_conflicting_source","auto_selection_allowed":false},{"variant_id":"C006-V06","label":"第2部まとめの時間一覧","source_passage_ids":["P205"],"steps_editorial":[],"dose_source_text":"1〜3分。個別手順は一覧に未記載。","breath_hold":true,"route":null,"status":"overview_only","auto_selection_allowed":false}]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I023","rule":"第6章：4〜5サイクル。第7章：3〜5セット。やさしい版は別の変種。各出典の手順を独立して表示する。"},{"issue_id":"I024","rule":"ボックス呼吸を現代呼吸法として紹介する。「Navy SEALsが考案」は起源資料が確認できるまで削除候補にする。"},{"issue_id":"I043","rule":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。"},{"issue_id":"I044","rule":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C007', '4-7-8呼吸', '["478呼吸","4–7–8呼吸"]', 'practice', '現代呼吸法', '比較対象', '就寝前・リラックスとして紹介', '[]', '["P24","P25","P26","P085"]', '["K016","K017","K003","K013","K014","K015"]', '["S002","S004"]', false, 'false', '[{"variant_id":"C007-V01","label":"第3章ファイルの4・7・8呼吸法（手順矛盾あり）","source_passage_ids":["P085"],"steps_editorial":["鼻から4秒吸う。","原文に「7秒間、息を止めずにキープ」とある。","口をすぼめ8秒吐く。"],"dose_source_text":"4〜8セット","breath_hold":null,"route":null,"status":"blocked_ambiguous_source","auto_selection_allowed":false}]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I025","rule":"「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C008', '長い呼気の呼吸', '["長く吐く呼吸","吐く息を長くする呼吸"]', 'practice', '本教材の基本呼吸法', '実践', '落ち着く・休息として紹介', '["椅子に座るか仰向けになり、肩の力を抜く。","鼻から自然に吸い、鼻または口から吸うより長く吐く。","3秒吸う・5秒吐く、または4秒吸う・6秒吐くという教材の例を使う。"]', '["P24","P25","P26","P081","P116","P120","P175","P187","P188","P227","P205"]', '["K016","K017","K013","K014","K015","K019","K034"]', '["S002","S004"]', false, 'false', '[{"variant_id":"C008-V01","label":"第6章の基本手順","source_passage_ids":["P081"],"steps_editorial":["椅子に座るか仰向けになり、肩の力を抜く。","鼻から自然に吸い、鼻または口から吸うより長く吐く。","3秒吸う・5秒吐く、または4秒吸う・6秒吐くという教材の例を使う。"],"dose_source_text":"5〜10呼吸","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V02","label":"第14章の長い呼気","source_passage_ids":["P116"],"steps_editorial":["鼻から3〜4秒吸う。","口から6〜8秒細く長く吐く。"],"dose_source_text":"3〜5回","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V03","label":"6-9 リカバリーの例","source_passage_ids":["P175"],"steps_editorial":["吸う4秒、吐く6〜8秒という原稿の例。","肋骨やお腹の動きを感じ、深さを強制しない。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V04","label":"7-11 保息を入れない代替例","source_passage_ids":["P187"],"steps_editorial":["3秒吸う。","5秒吐く。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V05","label":"7-12 本番10分前の例","source_passage_ids":["P188"],"steps_editorial":["4秒吸い、6秒吐く。"],"dose_source_text":"5〜10呼吸。本番10分前は開始する場面であり、10分間継続の意味ではない。","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V06","label":"14-3 面接・試験の例","source_passage_ids":["P227"],"steps_editorial":["鼻から3秒吸い、口から6〜8秒吐く。","面接では一度吐いてから答え、試験では問題へ戻る前の一呼吸として紹介。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V07","label":"第2部まとめの時間一覧","source_passage_ids":["P205"],"steps_editorial":[],"dose_source_text":"1〜3分。吸気呼気比はこの一覧に未記載。","breath_hold":false,"route":null,"status":"summary_only","auto_selection_allowed":false}]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I022","rule":"基本手順と図中の「自然な間」を別記する。記載のない固定保息や毎分回数へ換算しない。"},{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"},{"issue_id":"I043","rule":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。"},{"issue_id":"I044","rule":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C009', 'おやすみ呼吸', '["睡眠前呼吸","就寝前のリラックス呼吸"]', 'practice', '本教材の睡眠前呼吸法', '実践', '就寝前の準備として紹介', '["布団で仰向けになり、手を下腹部か肋骨の横に置く。","鼻から自然に吸い、3秒吸う・5秒吐くを目安にする。","深く吸おうと頑張らず、眠くなったら数えるのをやめる。"]', '["P24","P25","P086","P119","P120","P205"]', '["K017","K013","K014","K015","K019"]', '["S002","S004"]', false, 'false', '[{"variant_id":"C009-V01","label":"第8章の基本手順","source_passage_ids":["P086"],"steps_editorial":["布団で仰向けになり、手を下腹部か肋骨の横に置く。","鼻から自然に吸い、3秒吸う・5秒吐くを目安にする。","深く吸おうと頑張らず、眠くなったら数えるのをやめる。"],"dose_source_text":"5〜10呼吸","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C009-V02","label":"第9章の就寝前ゆるめ呼吸","source_passage_ids":["P119"],"steps_editorial":["4秒吸って6〜8秒吐く。","吐くたびに体が沈む感覚を持つ。"],"dose_source_text":"3分","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C009-V03","label":"第2部まとめの時間一覧","source_passage_ids":["P205"],"steps_editorial":[],"dose_source_text":"3〜5分","breath_hold":false,"route":null,"status":"summary_only","auto_selection_allowed":false}]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C010', '3分リカバリー呼吸', '["三分リカバリー呼吸"]', 'practice', '本教材の回復呼吸法', '実践', '回復・休息として紹介', '["楽に座り、肩・あご・みぞおちの力を抜く。","鼻から3〜4秒かけて軽く吸う。","口または鼻から6秒かけて細く長く吐く。"]', '["P24","P25","P087","P088","P089","P120"]', '["K017","K013","K014","K015","K019","K041"]', '["S004"]', false, 'false', '[{"variant_id":"C010-V01","label":"第9章の基本手順","source_passage_ids":["P087"],"steps_editorial":["楽に座り、肩・あご・みぞおちの力を抜く。","鼻から3〜4秒かけて軽く吸う。","口または鼻から6秒かけて細く長く吐く。"],"dose_source_text":"3分","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C010-V02","label":"第9章の開始・慣れた後の目安","source_passage_ids":["P088"],"steps_editorial":["慣れないうちは4秒吸う・6秒吐く。","慣れたら3秒吸う・6秒吐くという例。","苦しい場合は3秒吸う・4秒吐く、または自然呼吸より少し長く吐くという原稿記載。"],"dose_source_text":"3分","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C010-V03","label":"第14章の3分リカバリー呼吸","source_passage_ids":["P089"],"steps_editorial":["鼻から4秒吸う。","口から6秒吐き、肩やお腹の力をゆるめる。"],"dose_source_text":"3分","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false}]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C011', '呼吸カウント集中法', '[]', 'practice', '教材内の実践', '実践', '集中・注意を戻す', '["椅子に楽に座り、鼻から自然に呼吸する。","吐く息で1、次の吐く息で2と数える。","10まで数えたら1に戻る。","数を忘れたら1から。考え事に気づいたら呼吸へ戻る。"]', '["P090","P197","P205"]', '["K008","K035","K036","K037","K078"]', '["S002","S004"]', false, 'false', '[{"variant_id":"C011-V01","label":"7-7 吸気・呼気で同じ数を数える例","source_passage_ids":["P197"],"steps_editorial":["姿勢を整え、自然な呼吸をそのまま観察する。","本文の例は吸って1、吐いて1、吸って2、吐いて2。","考え事に気づいたら呼吸と数えることへ戻る。"],"dose_source_text":"1〜3分。何番まで数えるかはこの図に未記載。","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C011-V02","label":"第2部まとめの時間一覧","source_passage_ids":["P205"],"steps_editorial":[],"dose_source_text":"3分。数え方は一覧に未記載。","breath_hold":false,"route":null,"status":"summary_only","auto_selection_allowed":false}]', '[{"issue_id":"I045","rule":"図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C012', '脱力呼吸', '[]', 'practice', '教材内の実践', '実践', '肩まわりの力みに気づく', '["座るか仰向けになる。","肩を5秒すくめ、ストンと下ろす。","鼻から4秒吸い、口をすぼめて8秒吐く。"]', '["P091"]', '["K003","K026","K027"]', '["S004"]', false, 'false', '[]', '[{"issue_id":"I025","rule":"「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C013', '肋骨ひらき呼吸', '[]', 'practice', '教材内の実践', '実践', '肋骨の動きを観察する', '["椅子に座り、両手を肋骨の横に当てる。","鼻から吸い、肋骨が横に広がるのを感じる。","鼻から吐き、自然に戻るのを感じる。"]', '["P092"]', '["K003","K026","K027"]', '["S004"]', false, 'false', '[]', '[{"issue_id":"I025","rule":"「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C014', 'お腹＋肋骨呼吸', '[]', 'practice', '教材内の実践', '実践', 'お腹と肋骨の動きを観察する', '["座り、お腹と肋骨に手を当てる。","鼻から吸い、お腹と肋骨の動きを感じる。","吐くときは両方がやさしく戻るのを感じる。"]', '["P093"]', '["K003","K026","K027"]', '["S004"]', false, 'false', '[]', '[{"issue_id":"I025","rule":"「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C015', '就寝前のやさしい呼吸（第8章・保息なし）', '["4-7-8呼吸のやさしい版"]', 'practice', '教材内の実践', '実践', '就寝前の休息', '["仰向けか横向きの楽な姿勢になる。","鼻から4秒吸う。","息を止めず、口から7〜8秒かけて吐く。"]', '["P094"]', '["K038","K039"]', '["S002","S004"]', false, 'false', '[]', '[{"issue_id":"I026","rule":"名称案：就寝前のやさしい呼吸（第8章・保息なし）。原図の4秒吸う・7〜8秒吐くを記録し、7秒の保息は追加しない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C016', '体をゆるめる呼吸', '[]', 'practice', '教材内の実践', '実践', '就寝前に力みに気づく', '["仰向けになる。","吸うときに肋骨が少し広がるのを感じる。","吐くときに肩・胸・お腹をゆるめ、心の中で「重い」「ゆるむ」と言う。"]', '["P095","P205"]', '["K038","K039"]', '["S002","S004"]', false, 'false', '[{"variant_id":"C016-V01","label":"第2部まとめの時間一覧","source_passage_ids":["P205"],"steps_editorial":[],"dose_source_text":"3分","breath_hold":false,"route":null,"status":"summary_only","auto_selection_allowed":false}]', '[]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C017', '眠れない夜の呼吸観察', '[]', 'practice', '教材内の実践', '実践', '呼吸を操作せず観察する', '["呼吸を変えようとせず、吸う息・吐く息に気づく。","考え事に気づいたら「考えている」と気づき、呼吸へ戻る。"]', '["P096","P205"]', '["K038","K039"]', '["S002","S004"]', false, 'false', '[{"variant_id":"C017-V01","label":"第2部まとめの時間一覧","source_passage_ids":["P205"],"steps_editorial":[],"dose_source_text":"眠くなるまでという一覧表記。無期限に続ける実践指示としては採用しない。","breath_hold":false,"route":null,"status":"summary_only","auto_selection_allowed":false}]', '[]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C018', '姿勢リセット呼吸', '["肩こりリセット呼吸"]', 'practice', '教材内の実践', '実践', '姿勢と力みの観察', '["背すじを軽く伸ばし、一度肩をすくめてストンと落とす。","鼻から3〜4秒吸い、肋骨が横と後ろに広がるのを感じる。","口または鼻から6秒吐き、首・肩・あごの力を抜く。"]', '["P097","P120","P214"]', '["K041","K042","K043","K048","K049","K084"]', '["S004"]', false, 'false', '[]', '[]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C019', '朝の目覚め呼吸', '["目覚めの呼吸"]', 'practice', '教材内の実践', '実践', '起床後の準備', '["座るか立って背すじを軽く伸ばす。","肩・あご・お腹の力を抜き、鼻から3秒吸う。","胸・背中・肋骨の広がりを感じ、口または鼻から4〜5秒吐く。"]', '["P098","P120"]', '["K041","K042","K043","K048","K049"]', '["S004"]', false, 'false', '[]', '[]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C020', '手足あたため呼吸', '[]', 'practice', '教材内の実践', '実践', '冷えたときの体の観察', '["楽に座るか仰向けになる。両手をお腹に当てる。","鼻から4秒静かに吸い、お腹・背中・肋骨のやさしい広がりを感じる。","口または鼻から6秒吐き、肩・手・足の力を抜く。"]', '["P099","P120"]', '["K041","K042","K043","K048","K049"]', '["S004"]', false, 'false', '[]', '[]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C021', '運動後クールダウン呼吸', '["クールダウン呼吸"]', 'practice', '教材内の実践', '実践', '運動後に徐々に落ち着く', '["原稿では運動後に急に座り込まず、ゆっくり歩くところから始める。","呼吸が荒い間は秒数に合わせない。","少し落ち着いたら鼻から3〜4秒吸い、口から6秒吐く。","さらに落ち着いたら鼻呼吸に戻し、肩・胸・背中・脚の力を抜く。"]', '["P100","P120"]', '["K041","K042","K043","K048","K049"]', '["S004"]', false, 'false', '[]', '[]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C022', '横隔膜確認呼吸', '[]', 'practice', '教材内の実践', '実践', '横隔膜に伴う動きへの気づき', '["仰向けになり、片手を胸、片手をお腹に置く。","鼻から3〜4秒静かに吸い、お腹が少し広がるのを感じる。","口または鼻から4〜6秒ゆっくり吐き、お腹が自然に戻るのを感じる。"]', '["P101","P106","P120"]', '["K044","K045","K046","K047","K048"]', '["S004"]', false, 'false', '[]', '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C023', 'お腹の支え呼吸', '[]', 'practice', '教材内の実践', '実践', '体幹の支えへの気づき', '["背すじを軽く伸ばして座る。","鼻から3〜4秒吸い、お腹と背中をやさしく広げる。","口または鼻から4〜6秒吐き、お腹を薄くするよう意識する。","強く締めすぎず、息を止めずに姿勢を保つ。"]', '["P102","P106","P120"]', '["K044","K045","K046","K047","K048"]', '["S004"]', false, 'false', '[]', '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C024', 'お腹ゆるめ呼吸', '[]', 'practice', '教材内の実践', '実践', 'お腹まわりの緊張への気づき', '["楽に座るか仰向けになり、手をお腹に当てる。","鼻から3〜4秒静かに吸う。","口または鼻から6秒ほどかけて吐き、お腹の力を抜く。","みぞおち・下腹部・腰まわりをゆるめる。"]', '["P103","P106","P120"]', '["K044","K045","K046","K047","K048"]', '["S004"]', false, 'false', '[]', '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C025', '食前の整え呼吸', '[]', 'practice', '教材内の実践', '実践', '食事に入る準備', '["食べる前に姿勢を整え、肩・あご・みぞおちの力を抜く。","鼻から3〜4秒ゆっくり吸い、口または鼻から5〜6秒長く吐く。","3呼吸してから食べ始め、最初の一口をゆっくり噛む。"]', '["P104","P106","P120"]', '["K044","K045","K046","K047","K048"]', '["S004"]', false, 'false', '[]', '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C026', '食後の休息呼吸', '[]', 'practice', '教材内の実践', '実践', '食後の休息', '["食後すぐに強い運動をせず、背中を丸めすぎない楽な姿勢で座る。","お腹を締めつけない。鼻から3〜4秒静かに吸う。","口または鼻から5〜6秒ゆっくり吐く。"]', '["P105","P106","P120"]', '["K044","K045","K046","K047","K048"]', '["S004"]', false, 'false', '[]', '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C027', '本番前リセット呼吸', '[]', 'practice', '教材内の実践', '実践', '本番前の準備', '["足裏を床につけ、背すじを軽く伸ばす。","目線を一点に置き、鼻から3〜4秒吸う。","口または鼻から6秒吐き、肩・あご・手の力を抜く。","最後に自分にかける短い言葉を決める。"]', '["P107","P117","P227"]', '["K051","K052","K053","K057","K058"]', '["S004"]', false, 'false', '[{"variant_id":"C027-V01","label":"第14章の本番前リセット","source_passage_ids":["P117"],"steps_editorial":["背すじを伸ばし、視線を上げる。","鼻から3〜4秒吸い、口から4〜6秒吐く。","姿勢を整え、もう一度深く吸うという記載。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C027-V02","label":"14-3 プレゼンの例","source_passage_ids":["P227"],"steps_editorial":["鼻から3〜4秒吸い、口から6〜8秒吐く。","背すじを伸ばし、視線を整える。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C027-V03","label":"14-3 本番直前の例","source_passage_ids":["P227"],"steps_editorial":["鼻から3秒吸い、口から6〜8秒吐く。","短い言葉を自分に伝える。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false}]', '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C028', '切り替え呼吸', '[]', 'practice', '教材内の実践', '実践', '次の行動へ戻る', '["ミスや焦りに気づく。","肩を一度下げ、鼻または口から短く吸う。","口または鼻から長めに吐く。","次にやることを一つだけ決める。"]', '["P108","P118"]', '["K051","K052","K053","K057","K058"]', '["S004"]', false, 'false', '[{"variant_id":"C028-V01","label":"第14章の切り替え","source_passage_ids":["P118"],"steps_editorial":["軽く息を吐き切るという記載。","鼻から2〜3秒吸い、口から2〜3秒吐く。","「戻る」と心の中でつぶやく。"],"dose_source_text":"1呼吸","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false}]', '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C029', '動作リズム呼吸', '[]', 'practice', '教材内の実践', '概要・確認待ち', '動作と呼吸の関係を学ぶ', '["動作前に呼吸が止まっていないか確認する。","動きに合わせて吸う・吐くタイミングを考える。","力む場面で息を止めっぱなしにしない。","動作後は自然な呼吸に戻す。"]', '["P109","P227"]', '["K051","K052","K053"]', '["S004"]', false, 'false', '[{"variant_id":"C029-V01","label":"14-3 試合前の図","source_passage_ids":["P227"],"steps_editorial":["鼻から2〜3秒吸い、口から2〜3秒リズムよく吐くという図示。","競技や動作の準備へ移る。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"overview_only","auto_selection_allowed":false}]', '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C030', '力発揮呼吸', '[]', 'practice', '教材内の実践', '概要・確認待ち', '力を出す場面の呼吸を学ぶ', '["動作前に姿勢を整え、鼻または口から軽く吸う。","力を出す瞬間に短く吐く。","必要以上に息を止め続けず、動作後に呼吸を戻す。"]', '["P110"]', '["K051","K052","K053"]', '["S004"]', false, 'false', '[]', '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C031', '声の支え呼吸', '[]', 'practice', '教材内の実践', '実践', '発声の準備', '["背すじを軽く伸ばす。","鼻から3〜4秒吸い、お腹と背中が軽く広がるのを感じる。","「スー」と細く吐き、お腹を強く固めず支える。"]', '["P111"]', '["K054","K055","K086"]', '["S003","S004"]', false, 'false', '[]', '[]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C032', '発声前ウォームアップ呼吸', '[]', 'practice', '教材内の実践', '実践', '声を出す前の準備', '["背すじを軽く伸ばし、肩・あご・舌の力を抜く。","鼻から3〜4秒吸い、口から細く長く吐く。","軽くハミングし、リップロールを短く行う。","声を出す前にもう一度呼吸を整える。"]', '["P112","P113","P227"]', '["K054","K055","K086"]', '["S003","S004"]', false, 'false', '[{"variant_id":"C032-V01","label":"14-3 ステージの例","source_passage_ids":["P227"],"steps_editorial":["姿勢を整え、鼻から3秒吸う。","ハミングで息を流す。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false}]', '[{"issue_id":"I028","rule":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C033', 'ロングトーン練習', '[]', 'practice', '教材内の実践', '実践', '発声の補助練習', '["鼻から軽く吸う。","楽な高さで声を出し、声を大きくしすぎない。","息がなくなる前に終え、喉が苦しくなる前に休む。"]', '["P114"]', '["K054","K055"]', '["S003","S004"]', false, 'false', '[]', '[{"issue_id":"I028","rule":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。"}]', '5.0') ON CONFLICT (catalog_id) DO NOTHING;
